import{_ as n,o as e,c as a,a3 as s}from"./chunks/framework.bvEHUNtb.js";const h=JSON.parse('{"title":"13 六十甲子","description":"理解十天干与十二地支如何组合为完整的六十甲子时间编码。","frontmatter":{"title":"13 六十甲子","description":"理解十天干与十二地支如何组合为完整的六十甲子时间编码。","category":"guide","aliases":["六十甲子","甲子","干支纪时"]},"headers":[],"relativePath":"topics/traditional-wisdom/time/sexagenary-cycle.md","filePath":"topics/traditional-wisdom/time/sexagenary-cycle.md","lastUpdated":1786982540000}'),l={name:"topics/traditional-wisdom/time/sexagenary-cycle.md"};function p(i,t,d,r,o,c){return e(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="_13-·-六十甲子-天地合轨的完整时间编码" tabindex="-1">13 · 六十甲子：天地合轨的完整时间编码 <a class="header-anchor" href="#_13-·-六十甲子-天地合轨的完整时间编码" aria-label="Permalink to &quot;13 · 六十甲子：天地合轨的完整时间编码&quot;">​</a></h1><hr><h2 id="版本与引用说明" tabindex="-1">版本与引用说明 <a class="header-anchor" href="#版本与引用说明" aria-label="Permalink to &quot;版本与引用说明&quot;">​</a></h2><p>本篇主要依据：</p><ul><li>《史记·历书》（司马迁，约前91年）</li><li>《汉书·律历志》（班固，约公元80年）</li><li>《淮南子·天文训》（刘安等，约前139年）</li><li>《世本》（先秦至汉，已佚，辑本存）——&quot;黄帝命大挠作甲子&quot;来源</li><li>《尔雅·释天》（先秦至汉）——甲子训诂</li><li>考古参照：<strong>殷墟甲骨文</strong>（约前1300年），现存最早干支纪日实物</li></ul><hr><h2 id="一、体系定位-在知识树中的坐标" tabindex="-1">一、体系定位：在知识树中的坐标 <a class="header-anchor" href="#一、体系定位-在知识树中的坐标" aria-label="Permalink to &quot;一、体系定位：在知识树中的坐标&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>十天干（10）× 十二地支（12）</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>    最小公倍数 = 60</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>      六十甲子</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>  纪年 · 纪月 · 纪日 · 纪时</span></span>
<span class="line"><span>  四柱八字 · 奇门 · 六爻 · 六壬 · 择日</span></span></code></pre></div><p><strong>一句话定位</strong>：</p><blockquote><p>六十甲子是天干与地支两套系统<strong>咬合运转</strong>的完整周期——<br> 不是简单的10×12=120，而是10与12的<strong>最小公倍数60</strong>，<br> 是两套不同节律的天文周期，在数学上找到的<strong>最短公共轨道</strong>。</p></blockquote><h2 id="二、原典依据-四条核心文献" tabindex="-1">二、原典依据（四条核心文献） <a class="header-anchor" href="#二、原典依据-四条核心文献" aria-label="Permalink to &quot;二、原典依据（四条核心文献）&quot;">​</a></h2><h3 id="文献一-《史记·历书》——甲子纪年的官方确认" tabindex="-1">文献一：《史记·历书》——甲子纪年的官方确认 <a class="header-anchor" href="#文献一-《史记·历书》——甲子纪年的官方确认" aria-label="Permalink to &quot;文献一：《史记·历书》——甲子纪年的官方确认&quot;">​</a></h3><p>【原典】《史记》卷二十六·历书第四（司马迁，约公元前91年）</p><p>【原文节选】</p><blockquote><p>黄帝考定星历，建立五行，起消息，正闰余，于是有天地神祇物类之官，是谓五官。各司其序，不相乱也。</p></blockquote><p>《历书》确认了干支历法在黄帝时代的建立，并记载了从黄帝元年起的干支纪年序列。虽然&quot;黄帝建历&quot;的具体年代存在争议，但《史记》将其作为中华历法的起点，具有重要的文化史意义。</p><h3 id="文献二-《世本》——-大挠作甲子-的来源" tabindex="-1">文献二：《世本》——&quot;大挠作甲子&quot;的来源 <a class="header-anchor" href="#文献二-《世本》——-大挠作甲子-的来源" aria-label="Permalink to &quot;文献二：《世本》——&quot;大挠作甲子&quot;的来源&quot;">​</a></h3><p>【原典】《世本》（先秦至汉，已佚，清人辑本）</p><p>【原文】</p><blockquote><p>大挠作甲子。（《世本·作篇》）</p></blockquote><p>【注疏】唐代司马贞《史记索隐》引《世本》注：</p><blockquote><p>大挠，黄帝史官也。采五行之情，占斗机所建，始作甲乙以名日，谓之干；作子丑以名月，谓之支。有事于天则用日，有事于地则用辰，阴阳之别，故有支干名也。</p></blockquote><p>这是关于干支起源最详细的古代文献记载：</p><ul><li>作者：大挠（黄帝史官）</li><li>方法：观察北斗斗柄所指方位（斗建）</li><li>功能：天干纪日，地支纪月，天地分用</li></ul><h3 id="文献三-考古实物——殷墟甲骨文-约公元前1300年" tabindex="-1">文献三：考古实物——殷墟甲骨文（约公元前1300年） <a class="header-anchor" href="#文献三-考古实物——殷墟甲骨文-约公元前1300年" aria-label="Permalink to &quot;文献三：考古实物——殷墟甲骨文（约公元前1300年）&quot;">​</a></h3><p>1899年起陆续出土的殷墟甲骨文，包含大量干支纪日记录。其中<strong>完整的六十甲子表</strong>已被发现，证明六十甲子体系在商代中期已完全成型并用于日常纪日。</p><p>这将六十甲子的<strong>实证历史</strong>推至距今约3300年，远早于任何传世文献的记载。</p><hr><h3 id="文献四-《汉书·律历志》——数理逻辑的官方阐释" tabindex="-1">文献四：《汉书·律历志》——数理逻辑的官方阐释 <a class="header-anchor" href="#文献四-《汉书·律历志》——数理逻辑的官方阐释" aria-label="Permalink to &quot;文献四：《汉书·律历志》——数理逻辑的官方阐释&quot;">​</a></h3><p>【原典】《汉书》卷二十一·律历志（班固，约公元80年）</p><p>【原文节选】</p><blockquote><p>天六地五，数之常也。天以六制，地以五制。五六相乘，是为三十；三十相乘，是为六十。</p></blockquote><p>这是六十甲子<strong>数学来源</strong>的官方解释：</p><ul><li>天数以六为基（六律）</li><li>地数以五为基（五行）</li><li>5×6=30，30×2=60</li></ul><p>【说明】《汉书》的这个解释是从音律角度切入的，与&quot;10×12最小公倍数=60&quot;是不同角度的解释</p><h2 id="三、六十甲子完整表" tabindex="-1">三、六十甲子完整表 <a class="header-anchor" href="#三、六十甲子完整表" aria-label="Permalink to &quot;三、六十甲子完整表&quot;">​</a></h2><h3 id="_3-1-生成规则" tabindex="-1">3.1 生成规则 <a class="header-anchor" href="#_3-1-生成规则" aria-label="Permalink to &quot;3.1 生成规则&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天干（10）：甲乙丙丁戊己庚辛壬癸    → 循环</span></span>
<span class="line"><span>地支（12）：子丑寅卯辰巳午未申酉戌亥 → 循环</span></span>
<span class="line"><span></span></span>
<span class="line"><span>配对规则：</span></span>
<span class="line"><span>  阳干（甲丙戊庚壬）只配阳支（子寅辰午申戌）</span></span>
<span class="line"><span>  阴干（乙丁己辛癸）只配阴支（丑卯巳未酉亥）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>所以不是10×12=120，而是：</span></span>
<span class="line"><span>  10与12的最小公倍数 = 60</span></span>
<span class="line"><span>  （阴阳同性配对，自动过滤掉另外60个组合）</span></span></code></pre></div><h3 id="_3-2-六十甲子完整序列-六旬分组" tabindex="-1">3.2 六十甲子完整序列（六旬分组） <a class="header-anchor" href="#_3-2-六十甲子完整序列-六旬分组" aria-label="Permalink to &quot;3.2 六十甲子完整序列（六旬分组）&quot;">​</a></h3><p>六十甲子分为<strong>六旬</strong>，每旬十个，以甲开头：</p><p><strong>第一旬（甲子旬）</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">序</th><th style="text-align:center;">干支</th><th style="text-align:center;">五行</th><th style="text-align:center;">纳音</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;"><strong>甲子</strong></td><td style="text-align:center;">金</td><td style="text-align:center;">海中金</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">乙丑</td><td style="text-align:center;">金</td><td style="text-align:center;">海中金</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">丙寅</td><td style="text-align:center;">火</td><td style="text-align:center;">炉中火</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;">丁卯</td><td style="text-align:center;">火</td><td style="text-align:center;">炉中火</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:center;">戊辰</td><td style="text-align:center;">木</td><td style="text-align:center;">大林木</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:center;">己巳</td><td style="text-align:center;">木</td><td style="text-align:center;">大林木</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:center;">庚午</td><td style="text-align:center;">土</td><td style="text-align:center;">路旁土</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:center;">辛未</td><td style="text-align:center;">土</td><td style="text-align:center;">路旁土</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:center;">壬申</td><td style="text-align:center;">金</td><td style="text-align:center;">剑锋金</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:center;">癸酉</td><td style="text-align:center;">金</td><td style="text-align:center;">剑锋金</td></tr></tbody></table><p><strong>空亡：戌亥</strong></p><blockquote><p>空亡又称旬空，概念下面有讲</p></blockquote><p><strong>第二旬（甲戌旬）</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">序</th><th style="text-align:center;">干支</th><th style="text-align:center;">五行</th><th style="text-align:center;">纳音</th></tr></thead><tbody><tr><td style="text-align:center;">11</td><td style="text-align:center;"><strong>甲戌</strong></td><td style="text-align:center;">火</td><td style="text-align:center;">山头火</td></tr><tr><td style="text-align:center;">12</td><td style="text-align:center;">乙亥</td><td style="text-align:center;">火</td><td style="text-align:center;">山头火</td></tr><tr><td style="text-align:center;">13</td><td style="text-align:center;">丙子</td><td style="text-align:center;">水</td><td style="text-align:center;">涧下水</td></tr><tr><td style="text-align:center;">14</td><td style="text-align:center;">丁丑</td><td style="text-align:center;">水</td><td style="text-align:center;">涧下水</td></tr><tr><td style="text-align:center;">15</td><td style="text-align:center;">戊寅</td><td style="text-align:center;">土</td><td style="text-align:center;">城头土</td></tr><tr><td style="text-align:center;">16</td><td style="text-align:center;">己卯</td><td style="text-align:center;">土</td><td style="text-align:center;">城头土</td></tr><tr><td style="text-align:center;">17</td><td style="text-align:center;">庚辰</td><td style="text-align:center;">金</td><td style="text-align:center;">白蜡金</td></tr><tr><td style="text-align:center;">18</td><td style="text-align:center;">辛巳</td><td style="text-align:center;">金</td><td style="text-align:center;">白蜡金</td></tr><tr><td style="text-align:center;">19</td><td style="text-align:center;">壬午</td><td style="text-align:center;">木</td><td style="text-align:center;">杨柳木</td></tr><tr><td style="text-align:center;">20</td><td style="text-align:center;">癸未</td><td style="text-align:center;">木</td><td style="text-align:center;">杨柳木</td></tr></tbody></table><p><strong>空亡：申酉</strong></p><p><strong>第三旬（甲申旬）</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">序</th><th style="text-align:center;">干支</th><th style="text-align:center;">五行</th><th style="text-align:center;">纳音</th></tr></thead><tbody><tr><td style="text-align:center;">21</td><td style="text-align:center;"><strong>甲申</strong></td><td style="text-align:center;">水</td><td style="text-align:center;">泉中水</td></tr><tr><td style="text-align:center;">22</td><td style="text-align:center;">乙酉</td><td style="text-align:center;">水</td><td style="text-align:center;">泉中水</td></tr><tr><td style="text-align:center;">23</td><td style="text-align:center;">丙戌</td><td style="text-align:center;">土</td><td style="text-align:center;">屋上土</td></tr><tr><td style="text-align:center;">24</td><td style="text-align:center;">丁亥</td><td style="text-align:center;">土</td><td style="text-align:center;">屋上土</td></tr><tr><td style="text-align:center;">25</td><td style="text-align:center;">戊子</td><td style="text-align:center;">火</td><td style="text-align:center;">霹雳火</td></tr><tr><td style="text-align:center;">26</td><td style="text-align:center;">己丑</td><td style="text-align:center;">火</td><td style="text-align:center;">霹雳火</td></tr><tr><td style="text-align:center;">27</td><td style="text-align:center;">庚寅</td><td style="text-align:center;">木</td><td style="text-align:center;">松柏木</td></tr><tr><td style="text-align:center;">28</td><td style="text-align:center;">辛卯</td><td style="text-align:center;">木</td><td style="text-align:center;">松柏木</td></tr><tr><td style="text-align:center;">29</td><td style="text-align:center;">壬辰</td><td style="text-align:center;">水</td><td style="text-align:center;">长流水</td></tr><tr><td style="text-align:center;">30</td><td style="text-align:center;">癸巳</td><td style="text-align:center;">水</td><td style="text-align:center;">长流水</td></tr></tbody></table><p><strong>空亡：午未</strong></p><p><strong>第四旬（甲午旬）</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">序</th><th style="text-align:center;">干支</th><th style="text-align:center;">五行</th><th style="text-align:center;">纳音</th></tr></thead><tbody><tr><td style="text-align:center;">31</td><td style="text-align:center;"><strong>甲午</strong></td><td style="text-align:center;">金</td><td style="text-align:center;">沙中金</td></tr><tr><td style="text-align:center;">32</td><td style="text-align:center;">乙未</td><td style="text-align:center;">金</td><td style="text-align:center;">沙中金</td></tr><tr><td style="text-align:center;">33</td><td style="text-align:center;">丙申</td><td style="text-align:center;">火</td><td style="text-align:center;">山下火</td></tr><tr><td style="text-align:center;">34</td><td style="text-align:center;">丁酉</td><td style="text-align:center;">火</td><td style="text-align:center;">山下火</td></tr><tr><td style="text-align:center;">35</td><td style="text-align:center;">戊戌</td><td style="text-align:center;">木</td><td style="text-align:center;">平地木</td></tr><tr><td style="text-align:center;">36</td><td style="text-align:center;">己亥</td><td style="text-align:center;">木</td><td style="text-align:center;">平地木</td></tr><tr><td style="text-align:center;">37</td><td style="text-align:center;">庚子</td><td style="text-align:center;">土</td><td style="text-align:center;">壁上土</td></tr><tr><td style="text-align:center;">38</td><td style="text-align:center;">辛丑</td><td style="text-align:center;">土</td><td style="text-align:center;">壁上土</td></tr><tr><td style="text-align:center;">39</td><td style="text-align:center;">壬寅</td><td style="text-align:center;">金</td><td style="text-align:center;">金箔金</td></tr><tr><td style="text-align:center;">40</td><td style="text-align:center;">癸卯</td><td style="text-align:center;">金</td><td style="text-align:center;">金箔金</td></tr></tbody></table><p><strong>空亡：辰巳</strong></p><p><strong>第五旬（甲辰旬）</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">序</th><th style="text-align:center;">干支</th><th style="text-align:center;">五行</th><th style="text-align:center;">纳音</th></tr></thead><tbody><tr><td style="text-align:center;">41</td><td style="text-align:center;"><strong>甲辰</strong></td><td style="text-align:center;">火</td><td style="text-align:center;">覆灯火</td></tr><tr><td style="text-align:center;">42</td><td style="text-align:center;">乙巳</td><td style="text-align:center;">火</td><td style="text-align:center;">覆灯火</td></tr><tr><td style="text-align:center;">43</td><td style="text-align:center;">丙午</td><td style="text-align:center;">水</td><td style="text-align:center;">天河水</td></tr><tr><td style="text-align:center;">44</td><td style="text-align:center;">丁未</td><td style="text-align:center;">水</td><td style="text-align:center;">天河水</td></tr><tr><td style="text-align:center;">45</td><td style="text-align:center;">戊申</td><td style="text-align:center;">土</td><td style="text-align:center;">大驿土</td></tr><tr><td style="text-align:center;">46</td><td style="text-align:center;">己酉</td><td style="text-align:center;">土</td><td style="text-align:center;">大驿土</td></tr><tr><td style="text-align:center;">47</td><td style="text-align:center;">庚戌</td><td style="text-align:center;">金</td><td style="text-align:center;">钗钏金</td></tr><tr><td style="text-align:center;">48</td><td style="text-align:center;">辛亥</td><td style="text-align:center;">金</td><td style="text-align:center;">钗钏金</td></tr><tr><td style="text-align:center;">49</td><td style="text-align:center;">壬子</td><td style="text-align:center;">木</td><td style="text-align:center;">桑柘木</td></tr><tr><td style="text-align:center;">50</td><td style="text-align:center;">癸丑</td><td style="text-align:center;">木</td><td style="text-align:center;">桑柘木</td></tr></tbody></table><p><strong>空亡：寅卯</strong></p><p><strong>第六旬（甲寅旬）</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">序</th><th style="text-align:center;">干支</th><th style="text-align:center;">五行</th><th style="text-align:center;">纳音</th></tr></thead><tbody><tr><td style="text-align:center;">51</td><td style="text-align:center;"><strong>甲寅</strong></td><td style="text-align:center;">水</td><td style="text-align:center;">大溪水</td></tr><tr><td style="text-align:center;">52</td><td style="text-align:center;">乙卯</td><td style="text-align:center;">水</td><td style="text-align:center;">大溪水</td></tr><tr><td style="text-align:center;">53</td><td style="text-align:center;">丙辰</td><td style="text-align:center;">土</td><td style="text-align:center;">沙中土</td></tr><tr><td style="text-align:center;">54</td><td style="text-align:center;">丁巳</td><td style="text-align:center;">土</td><td style="text-align:center;">沙中土</td></tr><tr><td style="text-align:center;">55</td><td style="text-align:center;">戊午</td><td style="text-align:center;">火</td><td style="text-align:center;">天上火</td></tr><tr><td style="text-align:center;">56</td><td style="text-align:center;">己未</td><td style="text-align:center;">火</td><td style="text-align:center;">天上火</td></tr><tr><td style="text-align:center;">57</td><td style="text-align:center;">庚申</td><td style="text-align:center;">木</td><td style="text-align:center;">石榴木</td></tr><tr><td style="text-align:center;">58</td><td style="text-align:center;">辛酉</td><td style="text-align:center;">木</td><td style="text-align:center;">石榴木</td></tr><tr><td style="text-align:center;">59</td><td style="text-align:center;">壬戌</td><td style="text-align:center;">水</td><td style="text-align:center;">大海水</td></tr><tr><td style="text-align:center;">60</td><td style="text-align:center;">癸亥</td><td style="text-align:center;">水</td><td style="text-align:center;">大海水</td></tr></tbody></table><p><strong>空亡：子丑</strong></p><h2 id="四、空亡-六十甲子自带的-缺位" tabindex="-1">四、空亡：六十甲子自带的&quot;缺位&quot; <a class="header-anchor" href="#四、空亡-六十甲子自带的-缺位" aria-label="Permalink to &quot;四、空亡：六十甲子自带的&quot;缺位&quot;&quot;">​</a></h2><h3 id="_4-1-什么是空亡" tabindex="-1">4.1 什么是空亡？ <a class="header-anchor" href="#_4-1-什么是空亡" aria-label="Permalink to &quot;4.1 什么是空亡？&quot;">​</a></h3><p>每旬十个干支，天干用完了10个，地支却只走了10个（还剩2个没被配到）。这剩下的2个地支，就是这一旬的<strong>空亡</strong>（又称&quot;旬空&quot;）。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>甲子旬（甲子→癸酉）：</span></span>
<span class="line"><span>  走过的地支：子丑寅卯辰巳午未申酉（10个）</span></span>
<span class="line"><span>  没走到的：戌·亥</span></span>
<span class="line"><span>  → 甲子旬，戌亥空亡</span></span>
<span class="line"><span></span></span>
<span class="line"><span>六旬的空亡：</span></span>
<span class="line"><span>  甲子旬 → 戌亥空</span></span>
<span class="line"><span>  甲戌旬 → 申酉空</span></span>
<span class="line"><span>  甲申旬 → 午未空</span></span>
<span class="line"><span>  甲午旬 → 辰巳空</span></span>
<span class="line"><span>  甲辰旬 → 寅卯空</span></span>
<span class="line"><span>  甲寅旬 → 子丑空</span></span></code></pre></div><h3 id="_4-2-空亡的哲学意涵" tabindex="-1">4.2 空亡的哲学意涵 <a class="header-anchor" href="#_4-2-空亡的哲学意涵" aria-label="Permalink to &quot;4.2 空亡的哲学意涵&quot;">​</a></h3><blockquote><p>空亡者，虚而不实，有名无实之地。 ——《三命通会》</p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天干走完了，地支还没走完——</span></span>
<span class="line"><span>这两个&quot;没被天干照到&quot;的地支，</span></span>
<span class="line"><span>就像没有阳光照射的角落：</span></span>
<span class="line"><span>  有形，但无力</span></span>
<span class="line"><span>  存在，但虚化</span></span>
<span class="line"><span>  在场，但不发挥作用</span></span></code></pre></div><p>这不是神秘主义，是一个非常实用的<strong>状态标记</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>空亡 = 该地支所代表的事物，</span></span>
<span class="line"><span>       在这个时间段内&quot;虚而不实&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>应用：</span></span>
<span class="line"><span>  六爻中：某爻地支空亡 → 该爻代表的事不成立</span></span>
<span class="line"><span>  四柱中：某柱地支空亡 → 该柱代表的领域有缺失</span></span>
<span class="line"><span>  奇门中：某宫地支空亡 → 该宫方位不宜行动</span></span></code></pre></div><blockquote><p>【重要补充】&quot;冲空则实&quot;——空亡的地支，若被另一个地支冲，反而会被激活，从&quot;虚&quot;变&quot;实&quot;。<br> 这个规则将在第22篇《空亡旬空》中完整展开。</p></blockquote><h2 id="五、纳音五行-六十甲子的第三层编码" tabindex="-1">五、纳音五行：六十甲子的第三层编码 <a class="header-anchor" href="#五、纳音五行-六十甲子的第三层编码" aria-label="Permalink to &quot;五、纳音五行：六十甲子的第三层编码&quot;">​</a></h2><h3 id="_5-1-什么是纳音" tabindex="-1">5.1 什么是纳音？ <a class="header-anchor" href="#_5-1-什么是纳音" aria-label="Permalink to &quot;5.1 什么是纳音？&quot;">​</a></h3><p>每对干支（两个一组，如甲子·乙丑），除了各自的天干五行和地支五行之外，还有一个<strong>纳音五行</strong>——这是两者合并后，在音律层面产生的第三种五行属性。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>甲子 + 乙丑 = 海中金（纳音）</span></span>
<span class="line"><span>丙寅 + 丁卯 = 炉中火（纳音）</span></span>
<span class="line"><span>……</span></span></code></pre></div><h3 id="_5-2-纳音的来源" tabindex="-1">5.2 纳音的来源 <a class="header-anchor" href="#_5-2-纳音的来源" aria-label="Permalink to &quot;5.2 纳音的来源&quot;">​</a></h3><p>【原典】《汉书·律历志》</p><p>纳音来源于<strong>五音十二律</strong>的对应关系：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>古代音律：宫·商·角·徵·羽（五音）</span></span>
<span class="line"><span>对应五行：土·金·木·火·水</span></span>
<span class="line"><span></span></span>
<span class="line"><span>十二律管（十二律）与十二地支对应，</span></span>
<span class="line"><span>五音与五行对应，两者交叉产生六十甲子的纳音五行。</span></span></code></pre></div><p>这是古代<strong>声学与历法的交叉学科</strong>——古人认为，每个时间段都有其对应的&quot;音&quot;，音与五行相通，因此每对干支都有其纳音五行。</p><h3 id="_5-3-纳音的应用场景" tabindex="-1">5.3 纳音的应用场景 <a class="header-anchor" href="#_5-3-纳音的应用场景" aria-label="Permalink to &quot;5.3 纳音的应用场景&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>纳音五行主要用于：</span></span>
<span class="line"><span>  → 四柱命理（民间&quot;五行缺什么&quot;的判断，有时用纳音）</span></span>
<span class="line"><span>  → 择日（某些流派以纳音判断日子吉凶）</span></span>
<span class="line"><span>  → 起名（以纳音补充五行）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>在奇门遁甲和六爻中，纳音使用较少。</span></span>
<span class="line"><span>主流四柱命理（子平法）以天干地支本身的五行为主，纳音为辅助参考。</span></span></code></pre></div><p>【说明】纳音五行是六十甲子体系中<strong>争议较多</strong>的部分。<br> 不同流派对纳音的重视程度差异很大。<br> 本篇如实呈现，不强推某一立场。<br> 初学者优先掌握天干地支本身的五行，纳音可后续深入。</p><h2 id="六、六十甲子的四维应用-年·月·日·时" tabindex="-1">六、六十甲子的四维应用：年·月·日·时 <a class="header-anchor" href="#六、六十甲子的四维应用-年·月·日·时" aria-label="Permalink to &quot;六、六十甲子的四维应用：年·月·日·时&quot;">​</a></h2><h3 id="_6-1-纪年" tabindex="-1">6.1 纪年 <a class="header-anchor" href="#_6-1-纪年" aria-label="Permalink to &quot;6.1 纪年&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>六十年一轮回：</span></span>
<span class="line"><span>  2024年 = 甲辰年</span></span>
<span class="line"><span>  2025年 = 乙巳年</span></span>
<span class="line"><span>  2026年 = 丙午年</span></span>
<span class="line"><span>  ……</span></span>
<span class="line"><span>  2084年 = 甲辰年（下一轮）</span></span></code></pre></div><p><strong>计算方法</strong>：</p><p>$ \\text{干支序号} = (\\text{公历年份} - 3) \\mod 60 $</p><p>以2026年为例：$$ (2026 - 3) \\mod 60 = 2023 \\mod 60 = 43 $$</p><p>查表第43位 = <strong>丙午年</strong> ✓</p><h3 id="_6-2-纪月" tabindex="-1">6.2 纪月 <a class="header-anchor" href="#_6-2-纪月" aria-label="Permalink to &quot;6.2 纪月&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每年12个月，每月对应固定地支（月建）：</span></span>
<span class="line"><span>  正月（寅月）→ 天干随年干推算</span></span>
<span class="line"><span>  二月（卯月）→ 天干随年干推算</span></span>
<span class="line"><span>  ……</span></span>
<span class="line"><span></span></span>
<span class="line"><span>月干推算口诀（五虎遁年起月法）：</span></span>
<span class="line"><span>  甲己之年丙作首，</span></span>
<span class="line"><span>  乙庚之岁戊为头，</span></span>
<span class="line"><span>  丙辛必定寻庚起，</span></span>
<span class="line"><span>  丁壬壬位顺行流，</span></span>
<span class="line"><span>  若问戊癸何方发，</span></span>
<span class="line"><span>  甲寅之上好追求</span></span></code></pre></div><p>以丙午年（2026）为例：<br> 丙辛之年寻庚上 → 正月（寅月）从庚寅起，<br> 二月 = 辛卯，三月 = 壬辰……</p><h3 id="_6-3-纪日" tabindex="-1">6.3 纪日 <a class="header-anchor" href="#_6-3-纪日" aria-label="Permalink to &quot;6.3 纪日&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>六十天一轮回（约两个月）</span></span>
<span class="line"><span>这是干支纪日最原始的用途</span></span>
<span class="line"><span>甲骨文中大量的干支记录，主要就是纪日</span></span></code></pre></div><h3 id="_6-4-纪时" tabindex="-1">6.4 纪时 <a class="header-anchor" href="#_6-4-纪时" aria-label="Permalink to &quot;6.4 纪时&quot;">​</a></h3><p>补充：五鼠遁（日上起时法）</p><ul><li><strong>用途</strong>：根据给定的“日干”推算“子时的干支”，进而顺推全天的时干。</li><li><strong>为何叫“鼠”</strong>：一天十二个时辰，排时干时固定从地支“子”时开始，因子对应生肖鼠，故称“五鼠遁”。</li></ul><p>一天十二时辰，对应十二地支（固定）：</p><p>子时（23-01）· 丑时（01-03）· 寅时（03-05）……</p><p>时干随日干推算（五鼠遁日起时法）：</p><p>甲己还加甲，乙庚丙作初，丙辛从戊起，</p><p>丁壬庚子居，戊癸何方发，壬子是真途。</p><h2 id="七、-黄帝命大挠作甲子-——历史真相辨析" tabindex="-1">七、&quot;黄帝命大挠作甲子&quot;——历史真相辨析 <a class="header-anchor" href="#七、-黄帝命大挠作甲子-——历史真相辨析" aria-label="Permalink to &quot;七、&quot;黄帝命大挠作甲子&quot;——历史真相辨析&quot;">​</a></h2><p>这是一个需要<strong>如实呈现、不回避</strong>的考据问题。</p><h3 id="_7-1-传说记载" tabindex="-1">7.1 传说记载 <a class="header-anchor" href="#_7-1-传说记载" aria-label="Permalink to &quot;7.1 传说记载&quot;">​</a></h3><p>【原典】《世本·作篇》（辑本）：</p><blockquote><p>大挠作甲子。</p></blockquote><p>【注疏】《史记索隐》引：</p><blockquote><p>大挠，黄帝史官也。</p></blockquote><p>传说中，黄帝命史官大挠，观察北斗斗柄的指向，创制了干支体系，用于纪日纪月。</p><h3 id="_7-2-考古证据的修正" tabindex="-1">7.2 考古证据的修正 <a class="header-anchor" href="#_7-2-考古证据的修正" aria-label="Permalink to &quot;7.2 考古证据的修正&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>殷墟甲骨文（约前1300年）：</span></span>
<span class="line"><span>  → 已有完整六十甲子表</span></span>
<span class="line"><span>  → 大量干支纪日记录</span></span>
<span class="line"><span>  → 证明商代中期已完全成型</span></span>
<span class="line"><span></span></span>
<span class="line"><span>黄帝传说时代（约前2600年）：</span></span>
<span class="line"><span>  → 无直接考古证据支持干支体系已存在</span></span>
<span class="line"><span>  → 但也无证据证明不存在</span></span></code></pre></div><h3 id="_7-3-如实结论" tabindex="-1">7.3 如实结论 <a class="header-anchor" href="#_7-3-如实结论" aria-label="Permalink to &quot;7.3 如实结论&quot;">​</a></h3><h4 id="大挠作甲子-的文化意义" tabindex="-1">&quot;大挠作甲子&quot;的文化意义： <a class="header-anchor" href="#大挠作甲子-的文化意义" aria-label="Permalink to &quot;&quot;大挠作甲子&quot;的文化意义：&quot;">​</a></h4><p>将干支体系的创制归于黄帝时代，是中华文明&quot;追溯圣王&quot;传统的体现。</p><h4 id="考古可确认的" tabindex="-1">考古可确认的： <a class="header-anchor" href="#考古可确认的" aria-label="Permalink to &quot;考古可确认的：&quot;">​</a></h4><p>六十甲子在商代（约前1300年）已完全成型，这本身已是极为古老的成就</p><p>【诚实的边界】</p><ul><li>干支体系的最初创制时间，目前无法精确考证</li><li>&quot;黄帝时代&quot;是文化叙事，不是考古结论</li><li>当前&quot;环境&quot;下不可以一言蔽之</li></ul><h2 id="八、六十年一甲子-周期的哲学意涵" tabindex="-1">八、六十年一甲子：周期的哲学意涵 <a class="header-anchor" href="#八、六十年一甲子-周期的哲学意涵" aria-label="Permalink to &quot;八、六十年一甲子：周期的哲学意涵&quot;">​</a></h2><h3 id="_8-1-一甲子-为什么是六十年" tabindex="-1">8.1 &quot;一甲子&quot;为什么是六十年？ <a class="header-anchor" href="#_8-1-一甲子-为什么是六十年" aria-label="Permalink to &quot;8.1 &quot;一甲子&quot;为什么是六十年？&quot;">​</a></h3><p>现代人说&quot;活了一甲子&quot;为活了六十岁。为什么六十是一个完整周期？</p><ul><li>天干周期：10年一轮（五行各主两年）</li><li>地支周期：12年一轮（木星公转周期）</li></ul><p>两个周期同时回到起点： 10和12的最小公倍数 = 60</p><p>天干走了6轮，地支走了5轮；</p><p>天地同时回到&quot;甲子&quot;这个起点。</p><h3 id="_8-2-更大的周期" tabindex="-1">8.2 更大的周期 <a class="header-anchor" href="#_8-2-更大的周期" aria-label="Permalink to &quot;8.2 更大的周期&quot;">​</a></h3><p>六十甲子可以叠加：</p><ul><li>一元 = 60年（基础周期）</li><li>三元 = 180年（上元·中元·下元）</li></ul><blockquote><p>这是风水玄空飞星&quot;三元九运&quot;的来源</p></blockquote><p>更大周期：</p><p>邵雍《皇极经世》：元·会·运·世</p><p>一元 = 129600年 = 60甲子的更大嵌套</p><h3 id="补充一下不同体系的三元" tabindex="-1">补充一下不同体系的三元 <a class="header-anchor" href="#补充一下不同体系的三元" aria-label="Permalink to &quot;补充一下不同体系的三元&quot;">​</a></h3><h4 id="第一套-干支纪时体系的-三元" tabindex="-1">第一套：干支纪时体系的&quot;三元&quot; <a class="header-anchor" href="#第一套-干支纪时体系的-三元" aria-label="Permalink to &quot;第一套：干支纪时体系的&quot;三元&quot;&quot;">​</a></h4><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一甲子 = 60年（天干10 × 地支12 ÷ 最大公约数2）</span></span>
<span class="line"><span>一元   = 60年（= 1个甲子）</span></span>
<span class="line"><span>三元   = 上元 + 中元 + 下元 = 180年</span></span></code></pre></div><p>这里的&quot;元&quot;是<strong>干支周期的计数单位</strong>，<br> 60年走完一轮甲子，叫&quot;一元&quot;。<br> 三元 = 三个甲子 = 180年。</p><p><strong>用途</strong>：干支纪年、四柱、奇门遁甲的大周期框架。</p><h4 id="第二套-玄空飞星风水体系的-三元九运" tabindex="-1">第二套：玄空飞星风水体系的&quot;三元九运&quot; <a class="header-anchor" href="#第二套-玄空飞星风水体系的-三元九运" aria-label="Permalink to &quot;第二套：玄空飞星风水体系的&quot;三元九运&quot;&quot;">​</a></h4><ul><li>1 运 = 20年（九宫飞星轮换一次）</li><li>1 元 = 3 运 = 60年（上元·中元·下元各含三运）</li><li>三元 = 上元 + 中元 + 下元 = 180年</li><li>九运 = 9 × 20年 = 180年（一个完整大周期）</li></ul><p><strong>具体分布</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">元</th><th style="text-align:left;">运</th><th style="text-align:left;">年份</th><th style="text-align:left;">当令星</th></tr></thead><tbody><tr><td style="text-align:left;">上元</td><td style="text-align:left;">一运</td><td style="text-align:left;">1864–1883</td><td style="text-align:left;">一白水星</td></tr><tr><td style="text-align:left;">上元</td><td style="text-align:left;">二运</td><td style="text-align:left;">1884–1903</td><td style="text-align:left;">二黑土星</td></tr><tr><td style="text-align:left;">上元</td><td style="text-align:left;">三运</td><td style="text-align:left;">1904–1923</td><td style="text-align:left;">三碧木星</td></tr><tr><td style="text-align:left;">中元</td><td style="text-align:left;">四运</td><td style="text-align:left;">1924–1943</td><td style="text-align:left;">四绿木星</td></tr><tr><td style="text-align:left;">中元</td><td style="text-align:left;">五运</td><td style="text-align:left;">1944–1963</td><td style="text-align:left;">五黄土星</td></tr><tr><td style="text-align:left;">中元</td><td style="text-align:left;">六运</td><td style="text-align:left;">1964–1983</td><td style="text-align:left;">六白金星</td></tr><tr><td style="text-align:left;">下元</td><td style="text-align:left;">七运</td><td style="text-align:left;">1984–2003</td><td style="text-align:left;">七赤金星</td></tr><tr><td style="text-align:left;">下元</td><td style="text-align:left;">八运</td><td style="text-align:left;">2004–2023</td><td style="text-align:left;">八白土星</td></tr><tr><td style="text-align:left;"><strong>下元</strong></td><td style="text-align:left;"><strong>九运</strong></td><td style="text-align:left;"><strong>2024–2043</strong></td><td style="text-align:left;"><strong>九紫离火</strong></td></tr></tbody></table><p><strong>用途</strong>：玄空飞星风水、紫白飞星择日。</p><h3 id="两套体系的关系图" tabindex="-1">两套体系的关系图 <a class="header-anchor" href="#两套体系的关系图" aria-label="Permalink to &quot;两套体系的关系图&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  ┌─────────────────────────────────┐</span></span>
<span class="line"><span>                  │        180年 大周期               │</span></span>
<span class="line"><span>                  └─────────────────────────────────┘</span></span>
<span class="line"><span>                           ↙              ↘</span></span>
<span class="line"><span>        ┌──────────────────┐    ┌──────────────────────┐</span></span>
<span class="line"><span>        │  干支体系的三元   │    │  飞星体系的三元九运   │</span></span>
<span class="line"><span>        ├──────────────────┤    ├──────────────────────┤</span></span>
<span class="line"><span>        │ 1元 = 60年甲子   │    │ 1元 = 60年（3×20）   │</span></span>
<span class="line"><span>        │ 三元 = 180年     │    │ 1运 = 20年           │</span></span>
<span class="line"><span>        │                  │    │ 九运 = 180年         │</span></span>
<span class="line"><span>        │ 用于：干支纪年   │    │ 用于：风水·飞星      │</span></span>
<span class="line"><span>        │       奇门大周期 │    │       择日·布局      │</span></span>
<span class="line"><span>        └──────────────────┘    └──────────────────────┘</span></span>
<span class="line"><span>                  ↑                        ↑</span></span>
<span class="line"><span>            &quot;元&quot;= 甲子周期           &quot;元&quot;= 飞星换届周期</span></span></code></pre></div><h3 id="为什么会混淆" tabindex="-1">为什么会混淆？ <a class="header-anchor" href="#为什么会混淆" aria-label="Permalink to &quot;为什么会混淆？&quot;">​</a></h3><p>因为<strong>两套体系的大周期恰好都是180年</strong>，<br> &quot;上元·中元·下元&quot;的叫法也完全相同，<br> 但内部的最小单位不一样：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>干支体系：180年 ÷ 3元 = 60年/元（不再细分&quot;运&quot;）</span></span>
<span class="line"><span>飞星体系：180年 ÷ 9运 = 20年/运，3运 = 1元 = 60年</span></span></code></pre></div><p>两套体系<strong>共用了同一个180年框架</strong>，<br> 这不是巧合——古人认为180年是天地能量的一个完整轮回，<br> 干支与飞星都以此为基准，只是<strong>切分方式不同</strong>。</p><h3 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h3><blockquote><p><strong>&quot;20年一运&quot;是飞星风水体系的小周期；</strong><br><strong>&quot;60年一元&quot;是两套体系共用的中周期；</strong><br><strong>&quot;180年三元&quot;是两套体系共用的大周期。</strong></p><p>2025年处于<strong>下元九运（2024–2043）</strong>，<br> 是180年大周期的最后一运，<br> 2044年起将重启新一轮上元一运。</p></blockquote><h3 id="_8-3-周期思维的现代意义" tabindex="-1">8.3 周期思维的现代意义 <a class="header-anchor" href="#_8-3-周期思维的现代意义" aria-label="Permalink to &quot;8.3 周期思维的现代意义&quot;">​</a></h3><p>六十甲子揭示的核心思维：</p><p>世界不是线性的（不是一直向前），世界是周期性的（螺旋上升）</p><p>每个甲子年，不是简单的&quot;重复&quot;，而是在更高层次上的&quot;回归&quot;——</p><p>同样的天地能量组合，遇到不同的历史积累，产生不同的结果。</p><p>这就是为什么：历史会&quot;押韵&quot;，但不会&quot;重复&quot;。</p><blockquote><p>参考马克·吐温的说法，与甲子周期思维高度吻合</p></blockquote><h2 id="九、现代解读-六十甲子本质上是什么" tabindex="-1">九、现代解读：六十甲子本质上是什么？ <a class="header-anchor" href="#九、现代解读-六十甲子本质上是什么" aria-label="Permalink to &quot;九、现代解读：六十甲子本质上是什么？&quot;">​</a></h2><h3 id="_9-1-两个齿轮的咬合" tabindex="-1">9.1 两个齿轮的咬合 <a class="header-anchor" href="#_9-1-两个齿轮的咬合" aria-label="Permalink to &quot;9.1 两个齿轮的咬合&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>想象两个齿轮：</span></span>
<span class="line"><span>  小齿轮：10个齿（天干）</span></span>
<span class="line"><span>  大齿轮：12个齿（地支）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>两个齿轮同时转动：</span></span>
<span class="line"><span>  每转一格 = 一个干支组合</span></span>
<span class="line"><span>  转到两个齿轮同时回到起点 = 60格</span></span>
<span class="line"><span></span></span>
<span class="line"><span>六十甲子，就是这两个齿轮</span></span>
<span class="line"><span>咬合运转一圈的完整轨迹。</span></span></code></pre></div><p>这个模型解释了为什么六十甲子如此稳定：</p><p>它不是人为规定的，是两套独立的天文周期，在数学上自然产生的<strong>最短公共轨道</strong>。</p><h3 id="_9-2-四维时间坐标系的完成" tabindex="-1">9.2 四维时间坐标系的完成 <a class="header-anchor" href="#_9-2-四维时间坐标系的完成" aria-label="Permalink to &quot;9.2 四维时间坐标系的完成&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有了六十甲子，古人建立了一套</span></span>
<span class="line"><span>完整的四维时间坐标系：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>年柱（干支）= 大背景，60年周期</span></span>
<span class="line"><span>月柱（干支）= 季节背景，12月周期</span></span>
<span class="line"><span>日柱（干支）= 当日能量，60天周期</span></span>
<span class="line"><span>时柱（干支）= 当时能量，12时辰周期</span></span>
<span class="line"><span></span></span>
<span class="line"><span>四柱叠加 = 任意一个时间点的完整能量描述</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这就是&quot;四柱八字&quot;名称的来源：</span></span>
<span class="line"><span>  四柱 = 年·月·日·时</span></span>
<span class="line"><span>  八字 = 每柱一干一支，共八个字</span></span></code></pre></div><h3 id="_9-3-与现代坐标系的对比-两种时间观" tabindex="-1">9.3 与现代坐标系的对比：两种时间观 <a class="header-anchor" href="#_9-3-与现代坐标系的对比-两种时间观" aria-label="Permalink to &quot;9.3 与现代坐标系的对比：两种时间观&quot;">​</a></h3><p><strong>甲子坐标不是&quot;给时间贴标签&quot;，而是&quot;把时间纳入能量周期&quot;——让不同世纪的同类时间节点，产生可比较、可参照的意义</strong>。</p><h4 id="第一层-坐标形式的差异" tabindex="-1">第一层：坐标形式的差异 <a class="header-anchor" href="#第一层-坐标形式的差异" aria-label="Permalink to &quot;第一层：坐标形式的差异&quot;">​</a></h4><p><strong>现代时间坐标</strong>——线性定位系统：</p><p>$ T_{现代} = \\text{年} + \\text{月} + \\text{日} + \\text{时} $</p><p>$ \\text{例：} 2026年7月15日14时30分 $</p><p>回答的问题只有一个：<strong>你在时间轴上的哪个点？</strong></p><hr><p><strong>六十甲子坐标</strong>——周期能量系统：</p><p>$ T_{甲子} = \\text{年柱} \\otimes \\text{月柱} \\otimes \\text{日柱} \\otimes \\text{时柱} $</p><p>$ \\text{例：丙午年} \\cdot \\text{壬午月} \\cdot \\text{庚申日} \\cdot \\text{甲申时} $</p><p>回答的问题有四个：</p><ul><li>这个时间点处于哪个<strong>能量周期</strong>？</li><li>当下的<strong>天地气场</strong>是什么性质？</li><li>与历史上哪些时间节点<strong>同频共振</strong>？</li><li>这个时间容器里，<strong>藏着什么</strong>？</li></ul><h4 id="第二层-线性时间-vs-周期时间" tabindex="-1">第二层：线性时间 vs 周期时间 <a class="header-anchor" href="#第二层-线性时间-vs-周期时间" aria-label="Permalink to &quot;第二层：线性时间 vs 周期时间&quot;">​</a></h4><p>这是两种根本不同的<strong>时间哲学</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>线性时间观（现代）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>公元元年 ──────────────────────────────▶ 无限未来</span></span>
<span class="line"><span>         过去不可回，未来不可知</span></span>
<span class="line"><span>         每个时间点都是孤立的、一次性的</span></span>
<span class="line"><span></span></span>
<span class="line"><span>         公元1000年5月6日</span></span>
<span class="line"><span>         公元2000年5月6日</span></span>
<span class="line"><span>         ↑ 这两个日期，除了&quot;都是5月6日&quot;，</span></span>
<span class="line"><span>           没有任何内在联系可以挖掘。</span></span></code></pre></div><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>周期时间观（甲子）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ┌──────60年──────┐</span></span>
<span class="line"><span>    ↓                ↓</span></span>
<span class="line"><span>甲子年 → 乙丑年 → … → 癸亥年 → 甲子年（重启）</span></span>
<span class="line"><span>    ↑                           ↑</span></span>
<span class="line"><span>  相同的能量坐标，跨越世纪重现</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  历史上所有的&quot;丙午年&quot;，</span></span>
<span class="line"><span>  共享同一个能量坐标，</span></span>
<span class="line"><span>  可以横向比较、相互参照。</span></span></code></pre></div><h4 id="第三层-丙午年——同一坐标的历史回响" tabindex="-1">第三层：丙午年——同一坐标的历史回响 <a class="header-anchor" href="#第三层-丙午年——同一坐标的历史回响" aria-label="Permalink to &quot;第三层：丙午年——同一坐标的历史回响&quot;">​</a></h4><p>丙午，天干<strong>丙</strong>（阳火·太阳之火·文明之光），<br> 地支<strong>午</strong>（阳火·帝旺·极盛转折）。</p><p>$ \\text{丙午} = \\text{阳火} \\times \\text{阳火} = \\text{火势极盛，盛极必变} $</p><p>午为火之帝旺，丙为火之本气。<br> 两火叠加，是能量最烈、张力最大、最容易出现<strong>剧烈转折</strong>的年份坐标。</p><p>历史上的丙午年，发生了什么？</p><table tabindex="0"><thead><tr><th>历史上的丙午年</th><th></th><th>参考事件</th></tr></thead><tbody><tr><td><strong>1966年</strong></td><td></td><td>文化大革命</td></tr><tr><td>1906年</td><td></td><td>清廷宣布&quot;预备立宪&quot;，旧秩序开始松动；孙中山等人在广西发动镇南关起义</td></tr><tr><td>1126 年</td><td></td><td><strong>靖康之变前夕</strong>：金兵南下首次包围北宋都城开封。该年被宋代学者列为“赤马红羊劫”的开端，直接导致次年北宋的灭亡</td></tr><tr><td>公元 286 年</td><td></td><td>**五胡乱华，**南北朝分裂</td></tr><tr><td><strong>公元前195年</strong></td><td></td><td>**汉高祖刘邦驾崩，**次年（丁未年）爆发吕后之乱及诸吕掌权</td></tr></tbody></table><blockquote><p>这不是&quot;算命&quot;，也不是说丙午年&quot;注定出大事&quot;。<br> 而是说：<strong>当天地能量处于&quot;火势极盛&quot;的坐标时，<br> **<strong>人类社会中积累的张力，更容易在这个节点释放。</strong><br> 就像干燥的夏天，一粒火星更容易引发大火——<br> 不是火星&quot;命中注定&quot;，而是</strong>环境的能量状态提供了条件**。</p></blockquote><h4 id="第四层-甲子坐标的真正价值" tabindex="-1">第四层：甲子坐标的真正价值 <a class="header-anchor" href="#第四层-甲子坐标的真正价值" aria-label="Permalink to &quot;第四层：甲子坐标的真正价值&quot;">​</a></h4><p>现代时间系统解决的是<strong>导航问题</strong>：</p><blockquote><p>我在哪里？现在是几点？</p></blockquote><p>甲子时间系统解决的是<strong>意义问题</strong>：</p><blockquote><p>此刻的时间容器，装着什么性质的能量？<br> 历史上与此同频的时刻，发生过什么？<br> 我该如何在这个能量场中做出判断？</p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>公元2026年7月15日</span></span>
<span class="line"><span>→ 只告诉你：你在时间轴的第738,000+天</span></span>
<span class="line"><span></span></span>
<span class="line"><span>丙午年·壬午月·庚申日</span></span>
<span class="line"><span>→ 告诉你：</span></span>
<span class="line"><span>  · 年柱：丙午（火极盛，盛极转折）</span></span>
<span class="line"><span>  · 月柱：壬午（水火对冲，张力激烈）</span></span>
<span class="line"><span>  · 日柱：庚申（金气肃杀，决断之日）</span></span>
<span class="line"><span>  · 这个时间容器的能量性质是什么</span></span>
<span class="line"><span>  · 与哪些历史节点共享同一坐标</span></span>
<span class="line"><span>  · 适合什么，不适合什么</span></span></code></pre></div><p>公元纪年是一把<strong>尺子</strong>，精确测量你在时间轴上的位置。<br> 六十甲子是一张<strong>地图</strong>，告诉你此刻的地形、气候与历史上走过同一条路的人。</p><p>尺子告诉你&quot;在哪里&quot;，地图告诉你&quot;这里是什么&quot;。<br> 两者不是竞争关系——现代人需要的，是同时持有两种工具。</p><h2 id="十、承前启后" tabindex="-1">十、承前启后 <a class="header-anchor" href="#十、承前启后" aria-label="Permalink to &quot;十、承前启后&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上承：</span></span>
<span class="line"><span>  十天干（提供10个天的能量编码）</span></span>
<span class="line"><span>  十二地支（提供12个地的时空容器）</span></span>
<span class="line"><span>  阴阳论（阴阳同性配对，产生60而非120）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>本篇整合：</span></span>
<span class="line"><span>  六十甲子 = 天干 × 地支的完整咬合</span></span>
<span class="line"><span>          = 四维时间坐标系的完成</span></span>
<span class="line"><span>          = 空亡·纳音·旬的附加信息层</span></span>
<span class="line"><span></span></span>
<span class="line"><span>下启：</span></span>
<span class="line"><span>  → 二十四节气（月柱换算的天文基础）</span></span>
<span class="line"><span>  → 四柱八字（六十甲子是其全部操作基础）</span></span></code></pre></div><h2 id="十一、本章小结" tabindex="-1">十一、本章小结 <a class="header-anchor" href="#十一、本章小结" aria-label="Permalink to &quot;十一、本章小结&quot;">​</a></h2><p>六十甲子，是天干与地支两套系统<strong>咬合运转</strong>的完整周期，是中华时间体系的<strong>最终形态</strong>。</p><p><strong>三重价值</strong>：</p><ol><li>📐 <strong>数学价值</strong>：10与12的最小公倍数，是两套天文周期自然产生的最短公共轨道，不是人为规定</li><li>📅 <strong>历法价值</strong>：同时承担纪年·纪月·纪日·纪时四个维度，是人类历史上最精简的多维时间编码系统</li><li>🔮 <strong>术数价值</strong>：四柱八字·奇门遁甲·六爻·大六壬，所有体系的时间操作，都建立在六十甲子之上</li></ol><blockquote><p>学六十甲子，有三个层次：</p><p><strong>第一层</strong>：记住六十个干支的顺序和对应属性。<br> 这是工具层，熟练即可。</p><p><strong>第二层</strong>：理解空亡的逻辑——<br> 天干走完，地支还剩两个，<br> 这两个&quot;被遗忘的地支&quot;，就是这一旬的虚位。</p><p><strong>第三层</strong>：理解周期思维——<br> 六十年一甲子，不是重复，是螺旋。<br> 同样的天地能量，遇到不同的人，不同的时代，<br> 产生的，永远是新的故事。</p></blockquote><hr><p><em>文档版本：v1.0 · 六十甲子 ｜ 2026年7月 ｜ 持续更新中</em></p>`,205)])])}const x=n(l,[["render",p]]);export{h as __pageData,x as default};
